"""Structured logger setup for atcli using Python's standard logging + rich."""

import logging
from rich.logging import RichHandler


def get_logger(name: str) -> logging.Logger:
    """Return a logger configured with rich output.

    Calling get_logger multiple times with the same name returns the same
    instance (standard Python behaviour). The root handler is registered only
    once so repeated calls are safe.
    """
    logger = logging.getLogger(name)

    # Avoid adding duplicate handlers if already configured
    if logger.handlers:
        return logger

    # Propagate to root which has the rich handler; skip adding per-module handlers
    root = logging.getLogger()
    if not root.handlers:
        root.addHandler(
            RichHandler(
                rich_tracebacks=True,
                show_path=False,
                markup=False,
            )
        )
        root.setLevel(logging.INFO)
        # Suppress noisy third-party HTTP request logs
        logging.getLogger("httpx").setLevel(logging.WARNING)
        logging.getLogger("httpcore").setLevel(logging.WARNING)

    return logger
